INSERT INTO spell VALUES (414,'Magic Aura','magic aura','Illusion','Glamer',NULL,NULL,'Bard 1, Magic 1, Sorcerer/Wizard 1','V, S, F','1 standard action','Touch','One touched object weighing up to 5 lb./level',NULL,NULL,'One day/level (D)','None; see text','No','Alters object\'s magic aura.',NULL,NULL,NULL,'A small square of silk that must be passed over the object that receives the aura.','\n      <p>You alter an item\'s aura so that it registers to <i>detect</i> spells (and spells with similar capabilities) as though it were nonmagical, or a magic item of a kind you specify, or the subject of a spell you specify.</p>\n      <p>If the object bearing <i>magic aura</i> has <i>identify</i> cast on it or is similarly examined, the examiner recognizes that the aura is false and detects the object\'s actual qualities if he succeeds on a Will save. Otherwise, he believes the aura and no amount of testing reveals what the true magic is.</p>\n      <p>If the targeted item\'s own aura is exceptionally powerful (if it is an artifact, for instance), <i>magic aura</i> doesn\'t work.</p>\n      <p><i>Note:</i> A magic weapon, shield, or suit of armor must be a masterwork item, so a sword of average make, for example, looks suspicious if it has a magical aura.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Aura\" level=\"5\"><p><h5>Magic Aura</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Magic 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched object weighing up to 5 lb./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You alter an item\'s aura so that it registers to <i>detect</i> spells (and spells with similar capabilities) as though it were nonmagical, or a magic item of a kind you specify, or the subject of a spell you specify.</p><p>If the object bearing <i>magic aura</i> has <i>identify</i> cast on it or is similarly examined, the examiner recognizes that the aura is false and detects the object\'s actual qualities if he succeeds on a Will save. Otherwise, he believes the aura and no amount of testing reveals what the true magic is.</p><p>If the targeted item\'s own aura is exceptionally powerful (if it is an artifact, for instance), <i>magic aura</i> doesn\'t work.</p><p><i>Note:</i> A magic weapon, shield, or suit of armor must be a masterwork item, so a sword of average make, for example, looks suspicious if it has a magical aura.</p><p><i>Focus:</i> A small square of silk that must be passed over the object that receives the aura.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (415,'Magic Circle Against Chaos','magic circle against chaos','Abjuration',NULL,'Lawful',NULL,'Cleric 3, Law 3, Paladin 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Touch',NULL,'10-ft. -radius emanation from touched creature',NULL,'10 min./level','Will negates (harmless)','No; see text','As protection spells, but 10-ft. radius and 10 min./level.',NULL,NULL,'A little powdered silver with which you trace a 3-footdiameter circle on the floor (or ground) around the creature to be warded.',NULL,'\n      <p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from chaos</i> instead of <i>protection from evil</i>, and it can imprison a nonlawful called creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Circle Against Chaos\" level=\"5\"><p><h5>Magic Circle against Chaos</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Lawful]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Law 3, Paladin 3, Sorcerer/Wizard 3<br/></td></tr></table><p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from chaos</i> instead of <i>protection from evil</i>, and it can imprison a nonlawful called creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (416,'Magic Circle Against Evil','magic circle against evil','Abjuration',NULL,'Good',NULL,'Cleric 3, Good 3, Paladin 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Touch',NULL,'10-ft. -radius emanation from touched creature',NULL,'10 min./level','Will negates (harmless)','No; see text','As protection spells, but 10-ft. radius and 10 min./level.',NULL,NULL,'A little powdered silver with which you trace a 3-footdiameter circle on the floor (or ground) around the creature to be warded.',NULL,'\n      <p>All creatures within the area gain the effects of a <i>protection from evil</i> spell, and no nongood summoned creatures can enter the area either. You must overcome a creature\'s spell resistance in order to keep it at bay (as in the third function of <i>protection from evil</i>), but the deflection and resistance bonuses and the protection from mental control apply regardless of enemies\' spell resistance.</p>\n      <p>This spell has an alternative version that you may choose when casting it. A <i>magic circle against evil</i> can be focused inward rather than outward. When focused inward, the spell binds a nongood called creature (such as those called by the <i>lesser planar binding</i>,  <i>planar binding</i>,  and <i>greater planar binding</i> spells) for a maximum of 24 hours per caster level, provided that you cast the spell that calls the creature within 1 round of casting the <i>magic circle</i>. The creature cannot cross the circle\'s boundaries. If a creature too large to fit into the spell\'s area is the subject of the spell, the spell acts as a normal <i>protection from evil</i> spell for that creature only.</p>\n      <p>A <i>magic circle</i> leaves much to be desired as a trap. If the circle of powdered silver laid down in the process of spellcasting is broken, the effect immediately ends. The trapped creature can do nothing that disturbs the circle, directly or indirectly, but other creatures can. If the called creature has spell resistance, it can test the trap once a day. If you fail to overcome its spell resistance, the creature breaks free, destroying the circle. A creature capable of any form of dimensional travel (<i>astral projection</i>,  <i>blink</i>,  <i>dimension door</i>,  <i>etherealness</i>,  <i>gate</i>,  <i>plane shift</i>,  <i>shadow walk</i>,  <i>teleport</i>,  and similar abilities) can simply leave the circle through that means. You can prevent the creature\'s extradimensional escape by casting a <i>dimensional anchor</i> spell on it, but you must cast the spell before the creature acts. If you are successful, the <i>anchor</i> effect lasts as long as the <i>magic circle</i> does. The creature cannot reach across the <i>magic circle</i>,  but its ranged attacks (ranged weapons, spells, magical abilities, and the like) can. The creature can attack any target it can reach with its ranged attacks except for the circle itself.</p>\n      <p>You can add a special diagram (a two-dimensional bounded figure with no gaps along its circumference, augmented with various magical sigils) to make the <i>magic circle</i> more secure. Drawing the diagram by hand takes 10 minutes and requires a DC 20 Spellcraft check. You do not know the result of this check. If the check fails, the diagram is ineffective. You can take 10 when drawing the diagram if you are under no particular time pressure to complete the task. This task also takes 10 full minutes. If time is no factor at all, and you devote 3 hours and 20 minutes to the task, you can take 20.</p>\n      <p>A successful diagram allows you to cast a <i>dimensional anchor</i> spell on the <i>magic circle</i> during the round before casting any summoning spell. The <i>anchor</i> holds any called creatures in the <i>magic circle</i> for 24 hours per caster level. A creature cannot use its spell resistance against a <i>magic circle</i> prepared with a diagram, and none of its abilities or attacks can cross the diagram. If the creature tries a Charisma check to break free of the trap (see the <i>lesser planar binding</i> spell), the DC increases by 5. The creature is immediately released if anything disturbs the diagram-even a straw laid across it. However, the creature itself cannot disturb the diagram either directly or indirectly, as noted above.</p>\n      <p>This spell is not cumulative with <i>protection from evil</i> and vice versa.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Circle Against Evil\" level=\"5\"><p><h5>Magic Circle against Evil</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Good]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Good 3, Paladin 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius emanation from touched creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No; see text<br/></td></tr></table><p>All creatures within the area gain the effects of a <i>protection from evil</i> spell, and no nongood summoned creatures can enter the area either. You must overcome a creature\'s spell resistance in order to keep it at bay (as in the third function of <i>protection from evil</i>), but the deflection and resistance bonuses and the protection from mental control apply regardless of enemies\' spell resistance.</p><p>This spell has an alternative version that you may choose when casting it. A <i>magic circle against evil</i> can be focused inward rather than outward. When focused inward, the spell binds a nongood called creature (such as those called by the <i>lesser planar binding</i>,  <i>planar binding</i>,  and <i>greater planar binding</i> spells) for a maximum of 24 hours per caster level, provided that you cast the spell that calls the creature within 1 round of casting the <i>magic circle</i>. The creature cannot cross the circle\'s boundaries. If a creature too large to fit into the spell\'s area is the subject of the spell, the spell acts as a normal <i>protection from evil</i> spell for that creature only.</p><p>A <i>magic circle</i> leaves much to be desired as a trap. If the circle of powdered silver laid down in the process of spellcasting is broken, the effect immediately ends. The trapped creature can do nothing that disturbs the circle, directly or indirectly, but other creatures can. If the called creature has spell resistance, it can test the trap once a day. If you fail to overcome its spell resistance, the creature breaks free, destroying the circle. A creature capable of any form of dimensional travel (<i>astral projection</i>,  <i>blink</i>,  <i>dimension door</i>,  <i>etherealness</i>,  <i>gate</i>,  <i>plane shift</i>,  <i>shadow walk</i>,  <i>teleport</i>,  and similar abilities) can simply leave the circle through that means. You can prevent the creature\'s extradimensional escape by casting a <i>dimensional anchor</i> spell on it, but you must cast the spell before the creature acts. If you are successful, the <i>anchor</i> effect lasts as long as the <i>magic circle</i> does. The creature cannot reach across the <i>magic circle</i>,  but its ranged attacks (ranged weapons, spells, magical abilities, and the like) can. The creature can attack any target it can reach with its ranged attacks except for the circle itself.</p><p>You can add a special diagram (a two-dimensional bounded figure with no gaps along its circumference, augmented with various magical sigils) to make the <i>magic circle</i> more secure. Drawing the diagram by hand takes 10 minutes and requires a DC 20 Spellcraft check. You do not know the result of this check. If the check fails, the diagram is ineffective. You can take 10 when drawing the diagram if you are under no particular time pressure to complete the task. This task also takes 10 full minutes. If time is no factor at all, and you devote 3 hours and 20 minutes to the task, you can take 20.</p><p>A successful diagram allows you to cast a <i>dimensional anchor</i> spell on the <i>magic circle</i> during the round before casting any summoning spell. The <i>anchor</i> holds any called creatures in the <i>magic circle</i> for 24 hours per caster level. A creature cannot use its spell resistance against a <i>magic circle</i> prepared with a diagram, and none of its abilities or attacks can cross the diagram. If the creature tries a Charisma check to break free of the trap (see the <i>lesser planar binding</i> spell), the DC increases by 5. The creature is immediately released if anything disturbs the diagram-even a straw laid across it. However, the creature itself cannot disturb the diagram either directly or indirectly, as noted above.</p><p>This spell is not cumulative with <i>protection from evil</i> and vice versa.</p><p><i>Arcane Material Component:</i> A little powdered silver with which you trace a 3-footdiameter circle on the floor (or ground) around the creature to be warded.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (417,'Magic Circle Against Good','magic circle against good','Abjuration',NULL,'Evil',NULL,'Cleric 3, Evil 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Touch',NULL,'10-ft. -radius emanation from touched creature',NULL,'10 min./level','Will negates (harmless)','No; see text','As protection spells, but 10-ft. radius and 10 min./level.',NULL,NULL,'A little powdered silver with which you trace a 3-footdiameter circle on the floor (or ground) around the creature to be warded.',NULL,'\n      <p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from good</i> instead of <i>protection from evil</i>, and it can imprison a nonevil called creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Circle Against Good\" level=\"5\"><p><h5>Magic Circle against Good</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Evil 3, Sorcerer/Wizard 3<br/></td></tr></table><p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from good</i> instead of <i>protection from evil</i>, and it can imprison a nonevil called creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (418,'Magic Circle Against Law','magic circle against law','Abjuration',NULL,'Chaotic',NULL,'Chaos 3, Cleric 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Touch',NULL,'10-ft. -radius emanation from touched creature',NULL,'10 min./level','Will negates (harmless)','No; see text','As protection spells, but 10-ft. radius and 10 min./level.',NULL,NULL,'A little powdered silver with which you trace a 3-footdiameter circle on the floor (or ground) around the creature to be warded.',NULL,'\n      <p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from law</i> instead of <i>protection from evil</i>, and it can imprison a nonchaotic called creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Circle Against Law\" level=\"5\"><p><h5>Magic Circle against Law</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Chaotic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Chaos 3, Cleric 3, Sorcerer/Wizard 3<br/></td></tr></table><p>This spell functions like <i>magic circle against evil</i>,  except that it is similar to <i>protection from law</i> instead of <i>protection from evil</i>, and it can imprison a nonchaotic called creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (419,'Magic Fang','magic fang','Transmutation',NULL,NULL,NULL,'Druid 1, Ranger 1','V, S, DF','1 standard action','Touch','Living creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','One natural weapon of subject creature gets +1 on attack and damage rolls.',NULL,NULL,NULL,NULL,'\n      <p><i>Magic fang</i> gives one natural weapon of the subject a +1 enhancement bonus on attack and damage rolls. The spell can affect a slam attack, fist, bite, or other natural weapon. (The spell does not change an unarmed strike\'s damage from nonlethal damage to lethal damage.)</p>\n      <p><i>Magic fang</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Fang\" level=\"5\"><p><h5>Magic Fang</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Magic fang</i> gives one natural weapon of the subject a +1 enhancement bonus on attack and damage rolls. The spell can affect a slam attack, fist, bite, or other natural weapon. (The spell does not change an unarmed strike\'s damage from nonlethal damage to lethal damage.)</p><p><i>Magic fang</i> can be made permanent with a <i>permanency</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (420,'Magic Fang, Greater','greater magic fang','Transmutation',NULL,NULL,NULL,'Druid 3, Ranger 3','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 hour/level','Will negates (harmless)','Yes (harmless)','One natural weapon of subject creature gets +1/three caster levels on attack and damage rolls (max +5).',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>magic fang</i>, except that the enhancement bonus on attack and damage rolls is +1 per four caster levels (maximum +5).</p>\n      <p>Alternatively, you may imbue all of the creature\'s natural weapons with a +1 enhancement bonus (regardless of your caster level).</p>\n      <p><i>Greater magic fang</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Fang, Greater\" level=\"5\"><p><h5>Magic Fang, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 3, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr></table><p>This spell functions like <i>magic fang</i>, except that the enhancement bonus on attack and damage rolls is +1 per four caster levels (maximum +5).</p><p>Alternatively, you may imbue all of the creature\'s natural weapons with a +1 enhancement bonus (regardless of your caster level).</p><p><i>Greater magic fang</i> can be made permanent with a <i>permanency</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (421,'Magic Jar','magic jar','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S, F','1 standard action','Medium (100 ft. + 10 ft./level)','One creature',NULL,NULL,'1 hour/level or until you return to your body','Will negates; see text','Yes','Enables possession of another creature.',NULL,NULL,NULL,'A gem or crystal worth at least 100 gp.','\n      <p>By casting <i>magic jar</i>,  you place your soul in a gem or large crystal (known as the <i>magic jar</i>), leaving your body lifeless. Then you can attempt to take control of a nearby body, forcing its soul into the <i>magic jar</i>. You may move back to the jar (thereby returning the trapped soul to its body) and attempt to possess another body. The spell ends when you send your soul back to your own body, leaving the receptacle empty.</p>\n      <p>To cast the spell, the <i>magic jar</i> must be within spell range and you must know where it is, though you do not need line of sight or line of effect to it. When you transfer your soul upon casting, your body is, as near as anyone can tell, dead.</p>\n      <p>While in the <i>magic jar</i>,  you can sense and attack any life force within 10 feet per caster level (and on the same plane of existence). You do need line of effect from the jar to the creatures. You cannot determine the exact creature types or positions of these creatures. In a group of life forces, you can sense a difference of 4 or more Hit Dice between one creature and another and can determine whether a life force is powered by positive or negative energy. (Undead creatures are powered by negative energy. Only sentient undead creatures have, or are, souls.)</p>\n      <p>You could choose to take over either a stronger or a weaker creature, but which particular stronger or weaker creature you attempt to possess is determined randomly.</p>\n      <p>Attempting to possess a body is a full-round action. It is blocked by <i>protection from evil</i> or a similar ward. You possess the body and force the creature\'s soul into the <i>magic jar</i> unless the subject succeeds on a Will save. Failure to take over the host leaves your life force in the <i>magic jar</i>,  and the target automatically succeeds on further saving throws if you attempt to possess its body again.</p>\n      <p>If you are successful, your life force occupies the host body, and the host\'s life force is imprisoned in the <i>magic jar</i>. You keep your Intelligence, Wisdom, Charisma, level, class, base attack bonus, base save bonuses, alignment, and mental abilities. The body retains its Strength, Dexterity, Constitution, hit points, natural abilities, and automatic abilities. A body with extra limbs does not allow you to make more attacks (or more advantageous two-weapon attacks) than normal. You can\'t choose to activate the body\'s extraordinary or supernatural abilities. The creature\'s spells and spell-like abilities do not stay with the body.</p>\n      <p>As a standard action, you can shift freely from a host to the <i>magic jar</i> if within range, sending the trapped soul back to its body. The spell ends when you shift from the jar to your own body.</p>\n      <p>If the host body is slain, you return to the <i>magic jar</i>,  if within range, and the life force of the host departs (it is dead). If the host body is slain beyond the range of the spell, both you and the host die. Any life force with nowhere to go is treated as slain.</p>\n      <p>If the spell ends while you are in the <i>magic jar</i>,  you return to your body (or die if your body is out of range or destroyed). If the spell ends while you are in a host, you return to your body (or die, if it is out of range of your current position), and the soul in the <i>magic jar</i> returns to its body (or dies if it is out of range). Destroying the receptacle ends the spell, and the spell can be dispelled at either the <i>magic jar</i> or at the host\'s location.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Jar\" level=\"5\"><p><h5>Magic Jar</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level or until you return to your body<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>By casting <i>magic jar</i>,  you place your soul in a gem or large crystal (known as the <i>magic jar</i>), leaving your body lifeless. Then you can attempt to take control of a nearby body, forcing its soul into the <i>magic jar</i>. You may move back to the jar (thereby returning the trapped soul to its body) and attempt to possess another body. The spell ends when you send your soul back to your own body, leaving the receptacle empty.</p><p>To cast the spell, the <i>magic jar</i> must be within spell range and you must know where it is, though you do not need line of sight or line of effect to it. When you transfer your soul upon casting, your body is, as near as anyone can tell, dead.</p><p>While in the <i>magic jar</i>,  you can sense and attack any life force within 10 feet per caster level (and on the same plane of existence). You do need line of effect from the jar to the creatures. You cannot determine the exact creature types or positions of these creatures. In a group of life forces, you can sense a difference of 4 or more Hit Dice between one creature and another and can determine whether a life force is powered by positive or negative energy. (Undead creatures are powered by negative energy. Only sentient undead creatures have, or are, souls.)</p><p>You could choose to take over either a stronger or a weaker creature, but which particular stronger or weaker creature you attempt to possess is determined randomly.</p><p>Attempting to possess a body is a full-round action. It is blocked by <i>protection from evil</i> or a similar ward. You possess the body and force the creature\'s soul into the <i>magic jar</i> unless the subject succeeds on a Will save. Failure to take over the host leaves your life force in the <i>magic jar</i>,  and the target automatically succeeds on further saving throws if you attempt to possess its body again.</p><p>If you are successful, your life force occupies the host body, and the host\'s life force is imprisoned in the <i>magic jar</i>. You keep your Intelligence, Wisdom, Charisma, level, class, base attack bonus, base save bonuses, alignment, and mental abilities. The body retains its Strength, Dexterity, Constitution, hit points, natural abilities, and automatic abilities. A body with extra limbs does not allow you to make more attacks (or more advantageous two-weapon attacks) than normal. You can\'t choose to activate the body\'s extraordinary or supernatural abilities. The creature\'s spells and spell-like abilities do not stay with the body.</p><p>As a standard action, you can shift freely from a host to the <i>magic jar</i> if within range, sending the trapped soul back to its body. The spell ends when you shift from the jar to your own body.</p><p>If the host body is slain, you return to the <i>magic jar</i>,  if within range, and the life force of the host departs (it is dead). If the host body is slain beyond the range of the spell, both you and the host die. Any life force with nowhere to go is treated as slain.</p><p>If the spell ends while you are in the <i>magic jar</i>,  you return to your body (or die if your body is out of range or destroyed). If the spell ends while you are in a host, you return to your body (or die, if it is out of range of your current position), and the soul in the <i>magic jar</i> returns to its body (or dies if it is out of range). Destroying the receptacle ends the spell, and the spell can be dispelled at either the <i>magic jar</i> or at the host\'s location.</p><p><i>Focus:</i> A gem or crystal worth at least 100 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (422,'Magic Missile','magic missile','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 1','V, S','1 standard action','Medium (100 ft. + 10 ft./level)','Up to five creatures, no two of which can be more than 15 ft. apart',NULL,NULL,'Instantaneous','None','Yes','1d4+1 damage; +1 missile per two levels above 1st (max 5).',NULL,NULL,NULL,NULL,'\n      <p>A missile of magical energy darts forth from your fingertip and strikes its target, dealing 1d4+1 points of force damage.</p>\n      <p>The missile strikes unerringly, even if the target is in melee combat or has less than total cover or total concealment. Specific parts of a creature can\'t be singled out. Inanimate objects are not damaged by the spell.</p>\n      <p>For every two caster levels beyond 1st, you gain an additional missile-two at 3rd level, three at 5th, four at 7th, and the maximum of five missiles at 9th level or higher. If you shoot multiple missiles, you can have them strike a single creature or several creatures. A single missile can strike only one creature. You must designate targets before you check for spell resistance or roll damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Missile\" level=\"5\"><p><h5>Magic Missile</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to five creatures, no two of which can be more than 15 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A missile of magical energy darts forth from your fingertip and strikes its target, dealing 1d4+1 points of force damage.</p><p>The missile strikes unerringly, even if the target is in melee combat or has less than total cover or total concealment. Specific parts of a creature can\'t be singled out. Inanimate objects are not damaged by the spell.</p><p>For every two caster levels beyond 1st, you gain an additional missile-two at 3rd level, three at 5th, four at 7th, and the maximum of five missiles at 9th level or higher. If you shoot multiple missiles, you can have them strike a single creature or several creatures. A single missile can strike only one creature. You must designate targets before you check for spell resistance or roll damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (423,'Magic Mouth','magic mouth','Illusion','Glamer',NULL,NULL,'Bard 1, Sorcerer/Wizard 2','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature or object',NULL,NULL,'Permanent until discharged','Will negates (object)','Yes (object)','Speaks once when triggered.',NULL,'A small bit of honeycomb and jade dust worth 10 gp.',NULL,NULL,'\n      <p>This spell imbues the chosen object or creature with an enchanted mouth that suddenly appears and speaks its message the next time a specified event occurs. The message, which must be twenty-five or fewer words long, can be in any language known by you and can be delivered over a period of 10 minutes. The mouth cannot utter verbal components, use command words, or activate magical effects. It does, however, move according to the words articulated; if it were placed upon a statue, the mouth of the statue would move and appear to speak. Of course, <i>Magic mouth</i> can be placed upon a tree, rock, or any other object or creature.</p>\n      <p>The spell functions when specific conditions are fulfilled according to your command as set in the spell. Commands can be as general or as detailed as desired, although only visual and audible triggers can be used. Triggers react to what appears to be the case. Disguises and illusions can fool them. Normal darkness does not defeat a visual trigger, but magical <i>darkness</i> or <i>invisibility</i> does. Silent movement or magical <i>silence</i> defeats audible triggers. Audible triggers can be keyed to general types of noises or to a specific noise or spoken word. Actions can serve as triggers if they are visible or audible. A <i>Magic mouth</i> cannot distinguish alignment, level, Hit Dice, or class except by external garb.</p>\n      <p>The range limit of a trigger is 15 feet per caster level, so a 6th-level caster can command a <i>Magic mouth</i> to respond to triggers as far as 90 feet away. Regardless of range, the mouth can respond only to visible or audible triggers and actions in line of sight or within hearing distance.</p>\n      <p><i>Magic mouth</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Mouth\" level=\"5\"><p><h5>Magic Mouth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This spell imbues the chosen object or creature with an enchanted mouth that suddenly appears and speaks its message the next time a specified event occurs. The message, which must be twenty-five or fewer words long, can be in any language known by you and can be delivered over a period of 10 minutes. The mouth cannot utter verbal components, use command words, or activate magical effects. It does, however, move according to the words articulated; if it were placed upon a statue, the mouth of the statue would move and appear to speak. Of course, <i>Magic mouth</i> can be placed upon a tree, rock, or any other object or creature.</p><p>The spell functions when specific conditions are fulfilled according to your command as set in the spell. Commands can be as general or as detailed as desired, although only visual and audible triggers can be used. Triggers react to what appears to be the case. Disguises and illusions can fool them. Normal darkness does not defeat a visual trigger, but magical <i>darkness</i> or <i>invisibility</i> does. Silent movement or magical <i>silence</i> defeats audible triggers. Audible triggers can be keyed to general types of noises or to a specific noise or spoken word. Actions can serve as triggers if they are visible or audible. A <i>Magic mouth</i> cannot distinguish alignment, level, Hit Dice, or class except by external garb.</p><p>The range limit of a trigger is 15 feet per caster level, so a 6th-level caster can command a <i>Magic mouth</i> to respond to triggers as far as 90 feet away. Regardless of range, the mouth can respond only to visible or audible triggers and actions in line of sight or within hearing distance.</p><p><i>Magic mouth</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Material Component:</i> A small bit of honeycomb and jade dust worth 10 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (424,'Magic Stone','magic stone','Transmutation',NULL,NULL,NULL,'Cleric 1, Druid 1, Earth 1','V, S, DF','1 standard action','Touch','Up to three pebbles touched',NULL,NULL,'30 minutes or until discharged','Will negates (harmless, object)','Yes (harmless, object)','Three stones gain +1 on attack rolls, deal 1d6+1 damage.',NULL,NULL,NULL,NULL,'\n      <p>You transmute as many as three pebbles, which can be no larger than sling bullets, so that they strike with great force when thrown or slung. If hurled, they have a range increment of 20 feet. If slung, treat them as sling bullets (range increment 50 feet). The spell gives them a +1 enhancement bonus on attack and damage rolls. The user of the stones makes a normal ranged attack. Each stone that hits deals 1d6+1 points of damage (including the spell\'s enhancement bonus), or 2d6+2 points against undead.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Stone\" level=\"5\"><p><h5>Magic Stone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Druid 1, Earth 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to three pebbles touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>30 minutes or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p>You transmute as many as three pebbles, which can be no larger than sling bullets, so that they strike with great force when thrown or slung. If hurled, they have a range increment of 20 feet. If slung, treat them as sling bullets (range increment 50 feet). The spell gives them a +1 enhancement bonus on attack and damage rolls. The user of the stones makes a normal ranged attack. Each stone that hits deals 1d6+1 points of damage (including the spell\'s enhancement bonus), or 2d6+2 points against undead.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (425,'Magic Vestment','magic vestment','Transmutation',NULL,NULL,NULL,'Cleric 3, Strength 3, War 3','V, S, DF','1 standard action','Touch','Armor or shield touched',NULL,NULL,'1 hour/level','Will negates (harmless, object)','Yes (harmless, object)','Armor or shield gains +1 enhancement per four levels.',NULL,NULL,NULL,NULL,'\n      <p>You imbue a suit of armor or a shield with an enhancement bonus of +1 per four caster levels (maximum +5 at 20th level).</p>\n      <p>An outfit of regular clothing counts as armor that grants no AC bonus for the purpose of this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Vestment\" level=\"5\"><p><h5>Magic Vestment</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Strength 3, War 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Armor or shield touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p>You imbue a suit of armor or a shield with an enhancement bonus of +1 per four caster levels (maximum +5 at 20th level).</p><p>An outfit of regular clothing counts as armor that grants no AC bonus for the purpose of this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (426,'Magic Weapon','magic weapon','Transmutation',NULL,NULL,NULL,'Cleric 1, Paladin 1, Sorcerer/Wizard 1, War 1','V, S, DF','1 standard action','Touch','Weapon touched',NULL,NULL,'1 min./level','Will negates (harmless, object)','Yes (harmless, object)','Weapon gains +1 bonus.',NULL,NULL,NULL,NULL,'\n      <p><i>Magic weapon</i> gives a weapon a +1 enhancement bonus on attack and damage rolls. (An enhancement bonus does not stack with a masterwork weapon\'s +1 bonus on attack rolls.)</p>\n      <p>You can\'t cast this spell on a natural weapon, such as an unarmed strike (instead, see <i>magic fang</i>). A monk\'s unarmed strike is considered a weapon, and thus it can be enhanced by this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Weapon\" level=\"5\"><p><h5>Magic Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Paladin 1, Sorcerer/Wizard 1, War 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p><i>Magic weapon</i> gives a weapon a +1 enhancement bonus on attack and damage rolls. (An enhancement bonus does not stack with a masterwork weapon\'s +1 bonus on attack rolls.)</p><p>You can\'t cast this spell on a natural weapon, such as an unarmed strike (instead, see <i>magic fang</i>). A monk\'s unarmed strike is considered a weapon, and thus it can be enhanced by this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (427,'Magic Weapon, Greater','greater magic weapon','Transmutation',NULL,NULL,NULL,'Cleric 4, Paladin 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One weapon or fifty projectiles (all of which must be in contact with each other at the time of casting)',NULL,NULL,'1 hour/level','Will negates (harmless, object)','Yes (harmless, object)','+1/four levels (max +5).',NULL,NULL,'Powdered lime and carbon.',NULL,'\n      <p>This spell functions like <i>magic weapon</i>,  except that it gives a weapon an enhancement bonus on attack and damage rolls of +1 per four caster levels (maximum +5).</p>\n      <p>Alternatively, you can affect as many as fifty arrows, bolts, or bullets. The projectiles must be of the same kind, and they have to be together (in the same quiver or other container). Projectiles, but not thrown weapons, lose their transmutation when used. (Treat shuriken as projectiles, rather than as thrown weapons, for the purpose of this spell.)</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Magic Weapon, Greater\" level=\"5\"><p><h5>Magic Weapon, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Paladin 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One weapon or fifty projectiles (all of which must be in contact with each other at the time of casting)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p>This spell functions like <i>magic weapon</i>,  except that it gives a weapon an enhancement bonus on attack and damage rolls of +1 per four caster levels (maximum +5).</p><p>Alternatively, you can affect as many as fifty arrows, bolts, or bullets. The projectiles must be of the same kind, and they have to be together (in the same quiver or other container). Projectiles, but not thrown weapons, lose their transmutation when used. (Treat shuriken as projectiles, rather than as thrown weapons, for the purpose of this spell.)</p><p><i>Arcane Material Component:</i> Powdered lime and carbon.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (428,'Major Creation','major creation','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 5','V, S, M','10 minutes','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Unattended, nonmagical object of nonliving plant matter, up to 1 cu. ft./level','See text','None','No','As minor creation, plus stone and metal.',NULL,'A tiny piece of matter of the same sort of item you plan to create with minor creation.',NULL,NULL,'\n      <p>This spell functions like <i>minor creation</i>,  except that you can also create an object of mineral nature: stone, crystal, metal, or the like. The duration of the created item varies with its relative hardness and rarity, as indicated on the following table.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hardness and Rarity Examples</b><br/></td>\n<td><b>Duration</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Vegetable matter<br/></td>\n<td>2 hr./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Stone, crystal, base metals<br/></td>\n<td>1 hr./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Precious metals<br/></td>\n<td>20 min./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gems<br/></td>\n<td>10 min./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Rare metal<sup><b>1</b></sup><br/></td>\n<td>1 round/level<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 Includes adamantine, alchemical silver, and mithral. You can\'t use major creation to create a cold iron item.<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Major Creation\" level=\"5\"><p><h5>Major Creation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr></table><p>This spell functions like <i>minor creation</i>,  except that you can also create an object of mineral nature: stone, crystal, metal, or the like. The duration of the created item varies with its relative hardness and rarity, as indicated on the following table.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hardness and Rarity Examples</b><br/></td>\n<td><b>Duration</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Vegetable matter<br/></td>\n<td>2 hr./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Stone, crystal, base metals<br/></td>\n<td>1 hr./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Precious metals<br/></td>\n<td>20 min./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Gems<br/></td>\n<td>10 min./level<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Rare metal<sup><b>1</b></sup><br/></td>\n<td>1 round/level<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 Includes adamantine, alchemical silver, and mithral. You can\'t use major creation to create a cold iron item.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (429,'Major Image','major image','Illusion','Figment',NULL,NULL,'Bard 3, Sorcerer/Wizard 3','V, S, F','1 standard action','Long (400 ft. + 40 ft./level)',NULL,NULL,'Visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)','Concentration + 3 rounds','Will disbelief (if interacted with)','No','As silent image, plus sound, smell and thermal effects.',NULL,NULL,NULL,'A bit of fleece.','\n      <p>This spell functions like <i>silent image</i>,  except that sound, smell, and thermal illusions are included in the spell effect. While concentrating, you can move the image within the range.</p>\n      <p>The image disappears when struck by an opponent unless you cause the illusion to react appropriately.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Major Image\" level=\"5\"><p><h5>Major Image</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration + 3 rounds<br/></td></tr></table><p>This spell functions like <i>silent image</i>,  except that sound, smell, and thermal illusions are included in the spell effect. While concentrating, you can move the image within the range.</p><p>The image disappears when struck by an opponent unless you cause the illusion to react appropriately.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (430,'Make Whole','make whole','Transmutation',NULL,NULL,NULL,'Cleric 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One object of up to 10 cu. ft./level',NULL,NULL,'Instantaneous','Will negates (harmless, object)','Yes (harmless, object)','Repairs an object.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>mending</i>,  except that <i>make whole</i> completely repairs an object made of any substance, even one with multiple breaks, to be as strong as new. The spell does not restore the magical abilities of a broken magic item made whole, and it cannot mend broken magic rods, staffs, or wands. The spell does not repair items that have been warped, burned, disintegrated, ground to powder, melted, or vaporized, nor does it affect creatures (including constructs).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Make Whole\" level=\"5\"><p><h5>Make Whole</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One object of up to 10 cu. ft./level<br/></td></tr></table><p>This spell functions like <i>mending</i>,  except that <i>make whole</i> completely repairs an object made of any substance, even one with multiple breaks, to be as strong as new. The spell does not restore the magical abilities of a broken magic item made whole, and it cannot mend broken magic rods, staffs, or wands. The spell does not repair items that have been warped, burned, disintegrated, ground to powder, melted, or vaporized, nor does it affect creatures (including constructs).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (431,'Mark of Justice','mark of justice','Necromancy',NULL,NULL,NULL,'Cleric 5, Paladin 4','V, S, DF','10 minutes','Touch','Creature touched',NULL,NULL,'Permanent; see text','None','Yes','Designates action that will trigger curse on subject.',NULL,NULL,NULL,NULL,'\n      <p>You draw an indelible mark on the subject and state some behavior on the part of the subject that will activate the mark. When activated, the mark curses the subject. Typically, you designate some sort of criminal behavior that activates the mark, but you can pick any act you please. The effect of the mark is identical with the effect of <i>bestow curse</i>.</p>\n      <p>Since this spell takes 10 minutes to cast and involves writing on the target, you can cast it only on a creature that is willing or restrained.</p>\n      <p>Like the effect of <i>bestow curse</i>, a <i>mark of justice</i> cannot be dispelled, but it can be removed with a <i>break enchantment</i>, <i>limited wish</i>, <i>miracle</i>, <i>remove curse</i>, or <i>wish</i> spell. <i>Remove curse</i> works only if its caster level is equal to or higher than your <i>mark of justice</i> caster level. These restrictions apply regardless of whether the mark has activated.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mark of Justice\" level=\"5\"><p><h5>Mark of Justice</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Paladin 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You draw an indelible mark on the subject and state some behavior on the part of the subject that will activate the mark. When activated, the mark curses the subject. Typically, you designate some sort of criminal behavior that activates the mark, but you can pick any act you please. The effect of the mark is identical with the effect of <i>bestow curse</i>.</p><p>Since this spell takes 10 minutes to cast and involves writing on the target, you can cast it only on a creature that is willing or restrained.</p><p>Like the effect of <i>bestow curse</i>, a <i>mark of justice</i> cannot be dispelled, but it can be removed with a <i>break enchantment</i>, <i>limited wish</i>, <i>miracle</i>, <i>remove curse</i>, or <i>wish</i> spell. <i>Remove curse</i> works only if its caster level is equal to or higher than your <i>mark of justice</i> caster level. These restrictions apply regardless of whether the mark has activated.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (432,'Maze','maze','Conjuration','Teleportation',NULL,NULL,'Sorcerer/Wizard 8','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'See text','None','Yes','Traps subject in extradimensional maze.',NULL,NULL,NULL,NULL,'\n      <p>You banish the subject into an extradimensional labyrinth of force planes. Each round on its turn, it may attempt a DC 20 Intelligence check to escape the labyrinth as a full-round action. If the subject doesn\'t escape, the maze disappears after 10 minutes, forcing the subject to leave.</p>\n      <p>On escaping or leaving the maze, the subject reappears where it had been when the <i>maze</i> spell was cast. If this location is filled with a solid object, the subject appears in the nearest open space. Spells and abilities that move a creature within a plane, such as <i>teleport</i> and <i>dimension door</i>,  do not help a creature escape a <i>maze</i> spell, although a <i>plane shift</i> spell allows it to exit to whatever plane is designated in that spell. Minotaurs are not affected by this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Maze\" level=\"5\"><p><h5>Maze</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You banish the subject into an extradimensional labyrinth of force planes. Each round on its turn, it may attempt a DC 20 Intelligence check to escape the labyrinth as a full-round action. If the subject doesn\'t escape, the maze disappears after 10 minutes, forcing the subject to leave.</p><p>On escaping or leaving the maze, the subject reappears where it had been when the <i>maze</i> spell was cast. If this location is filled with a solid object, the subject appears in the nearest open space. Spells and abilities that move a creature within a plane, such as <i>teleport</i> and <i>dimension door</i>,  do not help a creature escape a <i>maze</i> spell, although a <i>plane shift</i> spell allows it to exit to whatever plane is designated in that spell. Minotaurs are not affected by this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (433,'Meld into Stone','meld into stone','Transmutation',NULL,'Earth',NULL,'Cleric 3, Druid 3','V, S, DF','1 standard action','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'You and your gear merge with stone.',NULL,NULL,NULL,NULL,'\n      <p><i>Meld into stone</i> enables you to meld your body and possessions into a single block of stone. The stone must be large enough to accommodate your body in all three dimensions. When the casting is complete, you and not more than 100 pounds of nonliving gear merge with the stone. If either condition is violated, the spell fails and is wasted.</p>\n      <p>While in the stone, you remain in contact, however tenuous, with the face of the stone through which you melded. You remain aware of the passage of time and can cast spells on yourself while hiding in the stone. Nothing that goes on outside the stone can be seen, but you can still hear what happens around you. Minor physical damage to the stone does not harm you, but its partial destruction (to the extent that you no longer fit within it) expels you and deals you 5d6 points of damage. The stone\'s complete destruction expels you and slays you instantly unless you make a DC 18 Fortitude save.</p>\n      <p>Any time before the duration expires, you can step out of the stone through the surface that you entered. If the spell\'s duration expires or the effect is dispelled before you voluntarily exit the stone, you are violently expelled and take 5d6 points of damage.</p>\n      <p>The following spells harm you if cast upon the stone that you are occupying: <i>Stone to flesh</i> expels you and deals you 5d6 points of damage. <i>Stone shape</i> deals you 3d6 points of damage but does not expel you. <i>Transmute rock to mud</i> expels you and then slays you instantly unless you make a DC 18 Fortitude save, in which case you are merely expelled. Finally, <i>passwall</i> expels you without damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Meld into Stone\" level=\"5\"><p><h5>Meld into Stone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Druid 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr></table><p><i>Meld into stone</i> enables you to meld your body and possessions into a single block of stone. The stone must be large enough to accommodate your body in all three dimensions. When the casting is complete, you and not more than 100 pounds of nonliving gear merge with the stone. If either condition is violated, the spell fails and is wasted.</p><p>While in the stone, you remain in contact, however tenuous, with the face of the stone through which you melded. You remain aware of the passage of time and can cast spells on yourself while hiding in the stone. Nothing that goes on outside the stone can be seen, but you can still hear what happens around you. Minor physical damage to the stone does not harm you, but its partial destruction (to the extent that you no longer fit within it) expels you and deals you 5d6 points of damage. The stone\'s complete destruction expels you and slays you instantly unless you make a DC 18 Fortitude save.</p><p>Any time before the duration expires, you can step out of the stone through the surface that you entered. If the spell\'s duration expires or the effect is dispelled before you voluntarily exit the stone, you are violently expelled and take 5d6 points of damage.</p><p>The following spells harm you if cast upon the stone that you are occupying: <i>Stone to flesh</i> expels you and deals you 5d6 points of damage. <i>Stone shape</i> deals you 3d6 points of damage but does not expel you. <i>Transmute rock to mud</i> expels you and then slays you instantly unless you make a DC 18 Fortitude save, in which case you are merely expelled. Finally, <i>passwall</i> expels you without damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (434,'Mending','mending','Transmutation',NULL,NULL,NULL,'Bard 0, Cleric 0, Druid 0, Sorcerer/Wizard 0','V, S','1 standard action','10 ft.','One object of up to 1 lb.',NULL,NULL,'Instantaneous','Will negates (harmless, object)','Yes (harmless, object)','Makes minor repairs on an object.',NULL,NULL,NULL,NULL,'\n      <p><i>Mending</i> repairs small breaks or tears in objects (but not warps, such as might be caused by a <i>warp wood</i> spell). It will weld broken metallic objects such as a ring, a chain link, a medallion, or a slender dagger, providing but one break exists.</p>\n      <p>Ceramic or wooden objects with multiple breaks can be invisibly rejoined to be as strong as new. A hole in a leather sack or a wineskin is completely healed over by <i>mending</i>. The spell can repair a magic item, but the item\'s magical abilities are not restored. The spell cannot mend broken magic rods, staffs, or wands, nor does it affect creatures (including constructs).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mending\" level=\"5\"><p><h5>Mending</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Cleric 0, Druid 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One object of up to 1 lb.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p><i>Mending</i> repairs small breaks or tears in objects (but not warps, such as might be caused by a <i>warp wood</i> spell). It will weld broken metallic objects such as a ring, a chain link, a medallion, or a slender dagger, providing but one break exists.</p><p>Ceramic or wooden objects with multiple breaks can be invisibly rejoined to be as strong as new. A hole in a leather sack or a wineskin is completely healed over by <i>mending</i>. The spell can repair a magic item, but the item\'s magical abilities are not restored. The spell cannot mend broken magic rods, staffs, or wands, nor does it affect creatures (including constructs).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (435,'Message','message','Transmutation',NULL,'Language-Dependent',NULL,'Bard 0, Sorcerer/Wizard 0','V, S, F','1 standard action','Medium (100 ft. + 10 ft./level)','One creature/level',NULL,NULL,'10 min./level','None','No','Whispered conversation at distance.',NULL,NULL,NULL,'A short piece of copper wire.','\n      <p>You can whisper messages and receive whispered replies with little chance of being overheard. You point your finger at each creature you want to receive the message. When you whisper, the whispered message is audible to all targeted creatures within range. Magical <i>silence</i>,  1 foot of stone, 1 inch of common metal (or a thin sheet of lead), or 3 feet of wood or dirt blocks the spell. The message does not have to travel in a straight line. It can circumvent a barrier if there is an open path between you and the subject, and the path\'s entire length lies within the spell\'s range. The creatures that receive the message can whisper a reply that you hear. The spell transmits sound, not meaning. It doesn\'t transcend language barriers.</p>\n      <p><i>Note:</i> To speak a message, you must mouth the words and whisper, possibly allowing observers the opportunity to read your lips.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Message\" level=\"5\"><p><h5>Message</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Language-Dependent]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can whisper messages and receive whispered replies with little chance of being overheard. You point your finger at each creature you want to receive the message. When you whisper, the whispered message is audible to all targeted creatures within range. Magical <i>silence</i>,  1 foot of stone, 1 inch of common metal (or a thin sheet of lead), or 3 feet of wood or dirt blocks the spell. The message does not have to travel in a straight line. It can circumvent a barrier if there is an open path between you and the subject, and the path\'s entire length lies within the spell\'s range. The creatures that receive the message can whisper a reply that you hear. The spell transmits sound, not meaning. It doesn\'t transcend language barriers.</p><p><i>Note:</i> To speak a message, you must mouth the words and whisper, possibly allowing observers the opportunity to read your lips.</p><p><i>Focus:</i> A short piece of copper wire.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (436,'Meteor Swarm','meteor swarm','Evocation',NULL,'Fire',NULL,'Sorcerer/Wizard 9','V, S','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'Four 40-ft. -radius spreads; see text',NULL,'Instantaneous','None or Reflex half; see text','Yes','Four exploding spheres each deal 6d6 fire damage.',NULL,NULL,NULL,NULL,'\n      <p><i>Meteor swarm</i> is a very powerful and spectacular spell that is similar to <i>fireball</i> in many aspects. When you cast it, four 2- foot-diameter spheres spring from your outstretched hand and streak in straight lines to the spots you select. The meteor spheres leave a fiery trail of sparks.</p>\n      <p>If you aim a sphere at a specific creature, you may make a ranged touch attack to strike the target with the meteor. Any creature struck by one of these spheres takes 2d6 points of bludgeoning damage (no save) and receives no saving throw against the sphere\'s fire damage (see below). If a targeted sphere misses its target, it simply explodes at the nearest corner of the target\'s space. You may aim more than one meteor at the same target.</p>\n      <p>Once a sphere reaches its destination, it explodes in a 40-foot-radius spread, dealing 6d6 points of fire damage to each creature in the area. If a creature is within the area of more than one sphere, it must save separately against each. (Fire resistance applies to each sphere\'s damage individually.)</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Meteor Swarm\" level=\"5\"><p><h5>Meteor Swarm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Four 40-ft. -radius spreads; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Reflex half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>Meteor swarm</i> is a very powerful and spectacular spell that is similar to <i>fireball</i> in many aspects. When you cast it, four 2- foot-diameter spheres spring from your outstretched hand and streak in straight lines to the spots you select. The meteor spheres leave a fiery trail of sparks.</p><p>If you aim a sphere at a specific creature, you may make a ranged touch attack to strike the target with the meteor. Any creature struck by one of these spheres takes 2d6 points of bludgeoning damage (no save) and receives no saving throw against the sphere\'s fire damage (see below). If a targeted sphere misses its target, it simply explodes at the nearest corner of the target\'s space. You may aim more than one meteor at the same target.</p><p>Once a sphere reaches its destination, it explodes in a 40-foot-radius spread, dealing 6d6 points of fire damage to each creature in the area. If a creature is within the area of more than one sphere, it must save separately against each. (Fire resistance applies to each sphere\'s damage individually.)</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (437,'Mind Blank','mind blank','Abjuration',NULL,NULL,NULL,'Protection 8, Sorcerer/Wizard 8','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'24 hours','Will negates (harmless)','Yes (harmless)','Subject is immune to mental/emotional magic and scrying.',NULL,NULL,NULL,NULL,'\n      <p>The subject is protected from all devices and spells that detect, influence, or read emotions or thoughts. This spell protects against all mind-affecting spells and effects as well as information gathering by divination spells or effects. <i>Mind blank</i> even foils <i>limited wish</i>, <i>miracle</i>, and <i>wish</i> spells when they are used in such a way as to affect the subject\'s mind or to gain information about it. In the case of scrying that scans an area the creature is in, such as <i>arcane eye</i>,  the spell works but the creature simply isn\'t detected. Scrying attempts that are targeted specifically at the subject do not work at all.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mind Blank\" level=\"5\"><p><h5>Mind Blank</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Protection 8, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject is protected from all devices and spells that detect, influence, or read emotions or thoughts. This spell protects against all mind-affecting spells and effects as well as information gathering by divination spells or effects. <i>Mind blank</i> even foils <i>limited wish</i>, <i>miracle</i>, and <i>wish</i> spells when they are used in such a way as to affect the subject\'s mind or to gain information about it. In the case of scrying that scans an area the creature is in, such as <i>arcane eye</i>,  the spell works but the creature simply isn\'t detected. Scrying attempts that are targeted specifically at the subject do not work at all.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (438,'Mind Fog','mind fog','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 5, Sorcerer/Wizard 5','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Fog spreads in 20-ft. radius, 20 ft. high','30 minutes and 2d6 rounds; see text','Will negates','Yes','Subjects in fog get -10 to Wis and Will checks.',NULL,NULL,NULL,NULL,'\n      <p><i>mind fog</i> produces a bank of thin mist that weakens the mental resistance of those caught in it. Creatures in the <i>mind fog</i> take a -10 competence penalty on Wisdom checks and Will saves. (A creature that successfully saves against the fog is not affected and need not make further saves even if it remains in the fog.) Affected creatures take the penalty as long as they remain in the fog and for 2d6 rounds thereafter. The fog is stationary and lasts for 30 minutes (or until dispersed by wind).</p>\n      <p>A moderate wind (11+ mph) disperses the fog in four rounds; a strong wind (21+ mph) disperses the fog in 1 round.</p>\n      <p>The fog is thin and does not significantly hamper vision.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mind Fog\" level=\"5\"><p><h5>Mind Fog</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Fog spreads in 20-ft. radius, 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>30 minutes and 2d6 rounds; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>mind fog</i> produces a bank of thin mist that weakens the mental resistance of those caught in it. Creatures in the <i>mind fog</i> take a -10 competence penalty on Wisdom checks and Will saves. (A creature that successfully saves against the fog is not affected and need not make further saves even if it remains in the fog.) Affected creatures take the penalty as long as they remain in the fog and for 2d6 rounds thereafter. The fog is stationary and lasts for 30 minutes (or until dispersed by wind).</p><p>A moderate wind (11+ mph) disperses the fog in four rounds; a strong wind (21+ mph) disperses the fog in 1 round.</p><p>The fog is thin and does not significantly hamper vision.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (439,'Minor Creation','minor creation','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 4','V, S, M','1 minute','0 ft.',NULL,NULL,'Unattended, nonmagical object of nonliving plant matter, up to 1 cu. ft./level','1 hour/level (D)','None','No','Creates one cloth or wood object.',NULL,'A tiny piece of matter of the same sort of item you plan to create with minor creation.',NULL,NULL,'\n      <p>You create a nonmagical, unattended object of nonliving, vegetable matter. The volume of the item created cannot exceed 1 cubic foot per caster level. You must succeed on an appropriate skill check to make a complex item.</p>\n      <p>Attempting to use any created object as a material component causes the spell to fail.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Minor Creation\" level=\"5\"><p><h5>Minor Creation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Unattended, nonmagical object of nonliving plant matter, up to 1 cu. ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You create a nonmagical, unattended object of nonliving, vegetable matter. The volume of the item created cannot exceed 1 cubic foot per caster level. You must succeed on an appropriate skill check to make a complex item.</p><p>Attempting to use any created object as a material component causes the spell to fail.</p><p><i>Material Component:</i> A tiny piece of matter of the same sort of item you plan to create with <i>minor creation</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (440,'Minor Image','minor image','Illusion','Figment',NULL,NULL,'Bard 2, Sorcerer/Wizard 2','V, S, F','1 standard action','Long (400 ft. + 40 ft./level)',NULL,NULL,'Visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)','Concentration +2 rounds','Will disbelief (if interacted with)','No','As silent image, plus some sound.',NULL,NULL,NULL,'A bit of fleece.','\n      <p>This spell functions like <i>silent image</i>, except that <i>minor image</i> includes some minor sounds but not understandable speech.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Minor Image\" level=\"5\"><p><h5>Minor Image</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration +2 rounds<br/></td></tr></table><p>This spell functions like <i>silent image</i>, except that <i>minor image</i> includes some minor sounds but not understandable speech.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (441,'Miracle','miracle','Evocation',NULL,NULL,NULL,'Cleric 9, Luck 9','V, S, XP; see text','1 standard action','See text','See text','See text','See text','See text','See text','Yes','Requests a deity\'s intercession.',NULL,NULL,NULL,NULL,'\n      <p>You don\'t so much cast a <i>miracle</i> as request one. You state what you would like to have happen and request that your deity (or the power you pray to for spells) intercede.</p>\n      <p>A <i>miracle</i> can do any of the following things.</p>\n      <ul>\n <li> Duplicate any cleric spell of 8th level or lower (including spells to which you have access because of your domains).</li>\n <li> Duplicate any other spell of 7th level or lower.</li>\n <li> Undo the harmful effects of certain spells, such as <i>feeblemind</i> or <i>insanity</i>.</li>\n <li> Have any effect whose power level is in line with the above effects.</li>\n</ul>\n      <p>If the <i>miracle</i> has any of the above effects, casting it has no experience point cost.</p>\n      <p>Alternatively, a cleric can make a very powerful request. Casting such a <i>miracle</i> costs the cleric 5,000 XP because of the powerful divine energies involved. Examples of especially powerful <i>miracles</i> of this sort could include the following.</p>\n      <ul>\n <li> Swinging the tide of a battle in your favor by raising fallen allies to continue fighting.</li>\n <li> Moving you and your allies, with all your and their gear, from one plane to another through planar barriers to a specific locale with no chance of error.</li>\n <li> Protecting a city from an earthquake, volcanic eruption, flood, or other major natural disaster.</li>\n</ul>\n      <p>In any event, a request that is out of line with the deity\'s (or alignment\'s) nature is refused.</p>\n      <p>A duplicated spell allows saving throws and spell resistance as normal, but the save DCs are as for a 9th-level spell. When a <i>miracle</i> duplicates a spell that has an XP cost, you must pay that cost. When a <i>miracle</i> spell duplicates a spell with a material component that costs more than 100 gp, you must provide that component.</p>\n      <p/>\n    ','5,000 XP (for some uses of the miracle spell; see above).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Miracle\" level=\"5\"><p><h5>Miracle</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 9, Luck 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target, Effect, or Area:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You don\'t so much cast a <i>miracle</i> as request one. You state what you would like to have happen and request that your deity (or the power you pray to for spells) intercede.</p><p>A <i>miracle</i> can do any of the following things.</p><ul>\n <li> Duplicate any cleric spell of 8th level or lower (including spells to which you have access because of your domains).</li>\n <li> Duplicate any other spell of 7th level or lower.</li>\n <li> Undo the harmful effects of certain spells, such as <i>feeblemind</i> or <i>insanity</i>.</li>\n <li> Have any effect whose power level is in line with the above effects.</li>\n</ul><p>If the <i>miracle</i> has any of the above effects, casting it has no experience point cost.</p><p>Alternatively, a cleric can make a very powerful request. Casting such a <i>miracle</i> costs the cleric 5,000 XP because of the powerful divine energies involved. Examples of especially powerful <i>miracles</i> of this sort could include the following.</p><ul>\n <li> Swinging the tide of a battle in your favor by raising fallen allies to continue fighting.</li>\n <li> Moving you and your allies, with all your and their gear, from one plane to another through planar barriers to a specific locale with no chance of error.</li>\n <li> Protecting a city from an earthquake, volcanic eruption, flood, or other major natural disaster.</li>\n</ul><p>In any event, a request that is out of line with the deity\'s (or alignment\'s) nature is refused.</p><p>A duplicated spell allows saving throws and spell resistance as normal, but the save DCs are as for a 9th-level spell. When a <i>miracle</i> duplicates a spell that has an XP cost, you must pay that cost. When a <i>miracle</i> spell duplicates a spell with a material component that costs more than 100 gp, you must provide that component.</p><p><i>XP Cost:</i> 5,000 XP (for some uses of the <i>miracle</i> spell; see above).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (442,'Mirage Arcana','mirage arcana','Illusion','Glamer',NULL,NULL,'Bard 5, Sorcerer/Wizard 5','V, S','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'One 20-ft. cube/level (S)',NULL,'Concentration +1 hour/level (D)','Will disbelief (if interacted with)','No','As hallucinatory terrain, plus structures.',NULL,'A stone, a twig, and a bit of green plant.',NULL,NULL,'\n      <p>This spell functions like <i>hallucinatory terrain</i>, except that it enables you to make any area appear to be something other than it is. The illusion includes audible, visual, tactile, and olfactory elements. Unlike <i>hallucinatory terrain</i>,  the spell can alter the appearance of structures (or add them where none are present). Still, it can\'t disguise, conceal, or add creatures (though creatures within the area might hide themselves within the illusion just as they can hide themselves within a real location).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mirage Arcana\" level=\"5\"><p><h5>Mirage Arcana</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>One 20-ft. cube/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration +1 hour/level (D)<br/></td></tr></table><p>This spell functions like <i>hallucinatory terrain</i>, except that it enables you to make any area appear to be something other than it is. The illusion includes audible, visual, tactile, and olfactory elements. Unlike <i>hallucinatory terrain</i>,  the spell can alter the appearance of structures (or add them where none are present). Still, it can\'t disguise, conceal, or add creatures (though creatures within the area might hide themselves within the illusion just as they can hide themselves within a real location).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (443,'Mirror Image','mirror image','Illusion','Figment',NULL,NULL,'Bard 2, Sorcerer/Wizard 2','V, S','1 standard action','Personal; see text','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'Creates decoy duplicates of you (1d4 +1 per three levels, max 8).',NULL,NULL,NULL,NULL,'\n      <p>Several illusory duplicates of you pop into being, making it difficult for enemies to know which target to attack. The figments stay near you and disappear when struck.</p>\n      <p><i>mirror image</i> creates 1d4 images plus one image per three caster levels (maximum eight images total). These figments separate from you and remain in a cluster, each within 5 feet of at least one other figment or you. You can move into and through a <i>mirror image</i>. When you and the <i>mirror image</i> separate, observers can\'t use vision or hearing to tell which one is you and which the image. The figments may also move through each other. The figments mimic your actions, pretending to cast spells when you cast a spell, drink potions when you drink a potion, levitate when you levitate, and so on.</p>\n      <p>Enemies attempting to attack you or cast spells at you must select from among indistinguishable targets. Generally, roll randomly to see whether the selected target is real or a figment. Any successful attack against an image destroys it. An image\'s AC is 10 + your size modifier + your Dex modifier. Figments seem to react normally to area spells (such as looking like they\'re burned or dead after being hit by a <i>fireball</i>).</p>\n      <p>While moving, you can merge with and split off from figments so that enemies who have learned which image is real are again confounded.</p>\n      <p>An attacker must be able to see the images to be fooled. If you are invisible or an attacker shuts his or her eyes, the spell has no effect. (Being unable to see carries the same penalties as being blinded.)</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mirror Image\" level=\"5\"><p><h5>Mirror Image</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr></table><p>Several illusory duplicates of you pop into being, making it difficult for enemies to know which target to attack. The figments stay near you and disappear when struck.</p><p><i>mirror image</i> creates 1d4 images plus one image per three caster levels (maximum eight images total). These figments separate from you and remain in a cluster, each within 5 feet of at least one other figment or you. You can move into and through a <i>mirror image</i>. When you and the <i>mirror image</i> separate, observers can\'t use vision or hearing to tell which one is you and which the image. The figments may also move through each other. The figments mimic your actions, pretending to cast spells when you cast a spell, drink potions when you drink a potion, levitate when you levitate, and so on.</p><p>Enemies attempting to attack you or cast spells at you must select from among indistinguishable targets. Generally, roll randomly to see whether the selected target is real or a figment. Any successful attack against an image destroys it. An image\'s AC is 10 + your size modifier + your Dex modifier. Figments seem to react normally to area spells (such as looking like they\'re burned or dead after being hit by a <i>fireball</i>).</p><p>While moving, you can merge with and split off from figments so that enemies who have learned which image is real are again confounded.</p><p>An attacker must be able to see the images to be fooled. If you are invisible or an attacker shuts his or her eyes, the spell has no effect. (Being unable to see carries the same penalties as being blinded.)</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (444,'Misdirection','misdirection','Illusion','Glamer',NULL,NULL,'Bard 2, Sorcerer/Wizard 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature or object, up to a 10-ft. cube in size',NULL,NULL,'1 hour/level','None or Will negates; see text','No','Misleads divinations for one creature or object.',NULL,NULL,NULL,NULL,'\n      <p>By means of this spell, you misdirect the information from divination spells that reveal auras (<i>detect evil</i>,  <i>detect magic</i>,  <i>discern lies</i>,  and the like). On casting the spell, you choose another object within range. For the duration of the spell, the subject of <i>misdirection</i> is detected as if it were the other object. (Neither the subject nor the other object gets a saving throw against this effect.) Detection spells provide information based on the second object rather than on the actual target of the detection unless the caster of the detection succeeds on a Will save. For instance, you could make yourself detect as a tree if one were within range at casting: not evil, not lying, not magical, neutral in alignment, and so forth. This spell does not affect other types of divination magic (<i>augury</i>,  <i>detect thoughts</i>,  <i>clairaudience/clairvoyance</i>,  and the like).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Misdirection\" level=\"5\"><p><h5>Misdirection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or object, up to a 10-ft. cube in size<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>By means of this spell, you misdirect the information from divination spells that reveal auras (<i>detect evil</i>,  <i>detect magic</i>,  <i>discern lies</i>,  and the like). On casting the spell, you choose another object within range. For the duration of the spell, the subject of <i>misdirection</i> is detected as if it were the other object. (Neither the subject nor the other object gets a saving throw against this effect.) Detection spells provide information based on the second object rather than on the actual target of the detection unless the caster of the detection succeeds on a Will save. For instance, you could make yourself detect as a tree if one were within range at casting: not evil, not lying, not magical, neutral in alignment, and so forth. This spell does not affect other types of divination magic (<i>augury</i>,  <i>detect thoughts</i>,  <i>clairaudience/clairvoyance</i>,  and the like).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (445,'Mislead','mislead','Illusion','Figment, Glamer',NULL,NULL,'Bard 5, Luck 6, Sorcerer/Wizard 6, Trickery 6','S','1 standard action','Close (25 ft. + 5 ft./2 levels)','You/one illusory double',NULL,'You/one illusory double','1 round/level (D) and concentration + 3 rounds; see text','None or Will disbelief (if interacted with); see text','No','Turns you invisible and creates illusory double.',NULL,NULL,NULL,NULL,'\n      <p>You become invisible (as <i>greater invisibility</i>, a glamer), and at the same time, an illusory double of you (as <i>major image</i>,  a figment) appears. You are then free to go elsewhere while your double moves away. The double appears within range but thereafter moves as you direct it (which requires concentration beginning on the first round after the casting). You can make the figment appear superimposed perfectly over your own body so that observers don\'t notice an image appearing and you turning invisible. You and the figment can then move in different directions. The double moves at your speed and can talk and gesture as if it were real, but it cannot attack or cast spells, though it can pretend to do so.</p>\n      <p>The illusory double lasts as long as you concentrate upon it, plus 3 additional rounds. After you cease concentration, the illusory double continues to carry out the same activity until the duration expires. The <i>greater invisibility</i> lasts for 1 round per level, regardless of concentration.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mislead\" level=\"5\"><p><h5>Mislead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment, Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Luck 6, Sorcerer/Wizard 6, Trickery 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target/Effect:</b><br/></td><td>You/one illusory double<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D) and concentration + 3 rounds; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will disbelief (if interacted with); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You become invisible (as <i>greater invisibility</i>, a glamer), and at the same time, an illusory double of you (as <i>major image</i>,  a figment) appears. You are then free to go elsewhere while your double moves away. The double appears within range but thereafter moves as you direct it (which requires concentration beginning on the first round after the casting). You can make the figment appear superimposed perfectly over your own body so that observers don\'t notice an image appearing and you turning invisible. You and the figment can then move in different directions. The double moves at your speed and can talk and gesture as if it were real, but it cannot attack or cast spells, though it can pretend to do so.</p><p>The illusory double lasts as long as you concentrate upon it, plus 3 additional rounds. After you cease concentration, the illusory double continues to carry out the same activity until the duration expires. The <i>greater invisibility</i> lasts for 1 round per level, regardless of concentration.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (446,'Mnemonic Enhancer','mnemonic enhancer','Transmutation',NULL,NULL,NULL,'Wizard 4','V, S, M, F','10 minutes','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'Wizard only. Prepares extra spells or retains one just cast.',NULL,'A piece of string, and ink consisting of squid secretion with black dragon\'s blood.',NULL,'An ivory plaque of at least 50 gp value.','\n      <p>Casting this spell allows you to prepare additional spells or retain spells recently cast. Pick one of these two versions when the spell is cast.</p>\n      <p><i>Prepare:</i> You prepare up to three additional levels of spells. A cantrip counts as 1/2 level for this purpose. You prepare and cast these spells normally.</p>\n      <p><i>Retain:</i> You retain any spell of 3rd level or lower that you had cast up to 1 round before you started casting the <i>mnemonic enhancer</i>. This restores the previously cast spell to your mind.</p>\n      <p>In either event, the spell or spells prepared or retained fade after 24 hours (if not cast).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mnemonic Enhancer\" level=\"5\"><p><h5>Mnemonic Enhancer</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr></table><p>Casting this spell allows you to prepare additional spells or retain spells recently cast. Pick one of these two versions when the spell is cast.</p><p><i>Prepare:</i> You prepare up to three additional levels of spells. A cantrip counts as 1/2 level for this purpose. You prepare and cast these spells normally.</p><p><i>Retain:</i> You retain any spell of 3rd level or lower that you had cast up to 1 round before you started casting the <i>mnemonic enhancer</i>. This restores the previously cast spell to your mind.</p><p>In either event, the spell or spells prepared or retained fade after 24 hours (if not cast).</p><p><i>Material Component:</i> A piece of string, and ink consisting of squid secretion with black dragon\'s blood.</p><p><i>Focus:</i> An ivory plaque of at least 50 gp value.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (447,'Modify Memory','modify memory','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 4','V, S','1 round; see text','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'Permanent','Will negates','Yes','Changes 5 minutes of subject\'s memories.',NULL,NULL,NULL,NULL,'\n      <p>You reach into the subject\'s mind and modify as many as 5 minutes of its memories in one of the following ways.</p>\n      <ul>\n <li> Eliminate all memory of an event the subject actually experienced. This spell cannot negate <i>charm</i>,  <i>geas/quest</i>,  <i>suggestion</i>,  or similar spells.</li>\n <li> Allow the subject to recall with perfect clarity an event it actually experienced.</li>\n <li> Change the details of an event the subject actually experienced.</li>\n <li> Implant a memory of an event the subject never experienced.</li>\n</ul>\n      <p>Casting the spell takes 1 round. If the subject fails to save, you proceed with the spell by spending as much as 5 minutes (a period of time equal to the amount of memory time you want to modify) visualizing the memory you wish to modify in the subject. If your concentration is disturbed before the visualization is complete, or if the subject is ever beyond the spell\'s range during this time, the spell is lost.</p>\n      <p>A modified memory does not necessarily affect the subject\'s actions, particularly if it contradicts the creature\'s natural inclinations. An illogical modified memory is dismissed by the creature as a bad dream or a memory muddied by too much wine.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Modify Memory\" level=\"5\"><p><h5>Modify Memory</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You reach into the subject\'s mind and modify as many as 5 minutes of its memories in one of the following ways.</p><ul>\n <li> Eliminate all memory of an event the subject actually experienced. This spell cannot negate <i>charm</i>,  <i>geas/quest</i>,  <i>suggestion</i>,  or similar spells.</li>\n <li> Allow the subject to recall with perfect clarity an event it actually experienced.</li>\n <li> Change the details of an event the subject actually experienced.</li>\n <li> Implant a memory of an event the subject never experienced.</li>\n</ul><p>Casting the spell takes 1 round. If the subject fails to save, you proceed with the spell by spending as much as 5 minutes (a period of time equal to the amount of memory time you want to modify) visualizing the memory you wish to modify in the subject. If your concentration is disturbed before the visualization is complete, or if the subject is ever beyond the spell\'s range during this time, the spell is lost.</p><p>A modified memory does not necessarily affect the subject\'s actions, particularly if it contradicts the creature\'s natural inclinations. An illogical modified memory is dismissed by the creature as a bad dream or a memory muddied by too much wine.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (448,'Moment of Prescience','moment of prescience','Divination',NULL,NULL,NULL,'Luck 8, Sorcerer/Wizard 8','V, S','1 standard action','Personal','You',NULL,NULL,'1 hour/level or until discharged',NULL,NULL,'You gain insight bonus on single attack roll, check, or save.',NULL,NULL,NULL,NULL,'\n      <p>This spell grants you a powerful sixth sense in relation to yourself. Once during the spell\'s duration, you may choose to use its effect. This spell grants you an insight bonus equal to your caster level (maximum +25) on any single attack roll, opposed ability or skill check, or saving throw. Alternatively, you can apply the insight bonus to your AC against a single attack (even if flat-footed). Activating the effect doesn\'t take an action; you can even activate it on another character\'s turn if needed. You must choose to use the <i>moment of prescience</i> before you make the roll it is to modify. Once used, the spell ends.</p>\n      <p>You can\'t have more than one <i>moment of prescience</i> active on you at the same time.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Moment of Prescience\" level=\"5\"><p><h5>Moment of Prescience</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Luck 8, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level or until discharged<br/></td></tr></table><p>This spell grants you a powerful sixth sense in relation to yourself. Once during the spell\'s duration, you may choose to use its effect. This spell grants you an insight bonus equal to your caster level (maximum +25) on any single attack roll, opposed ability or skill check, or saving throw. Alternatively, you can apply the insight bonus to your AC against a single attack (even if flat-footed). Activating the effect doesn\'t take an action; you can even activate it on another character\'s turn if needed. You must choose to use the <i>moment of prescience</i> before you make the roll it is to modify. Once used, the spell ends.</p><p>You can\'t have more than one <i>moment of prescience</i> active on you at the same time.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (449,'Mount','mount','Conjuration','Summoning',NULL,NULL,'Sorcerer/Wizard 1','V, S, M','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One mount','2 hours/level (D)','None','No','Summons riding horse for 2 hours/level.',NULL,'A bit of horse hair.',NULL,NULL,'\n      <p>You summon a light horse or a pony (your choice) to serve you as a mount. The steed serves willingly and well. The mount comes with a bit and bridle and a riding saddle.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mount\" level=\"5\"><p><h5>Mount</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One mount<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You summon a light horse or a pony (your choice) to serve you as a mount. The steed serves willingly and well. The mount comes with a bit and bridle and a riding saddle.</p><p><i>Material Component:</i> A bit of horse hair.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (450,'Move Earth','move earth','Transmutation',NULL,'Earth',NULL,'Druid 6, Sorcerer/Wizard 6','V, S, M','See text','Long (400 ft. + 40 ft./level)',NULL,'Dirt in an area up to 750 ft. square and up to 10 ft. deep (S)',NULL,'Instantaneous','None','No','Digs trenches and build hills.',NULL,'A mixture of soils (clay, loam, and sand) in a small bag, and an iron blade.',NULL,NULL,'\n      <p><i>Move earth</i> moves dirt (clay, loam, sand), possibly collapsing embankments, moving hillocks, shifting dunes, and so forth.</p>\n      <p>However, in no event can rock formations be collapsed or moved. The area to be affected determines the casting time. For every 150-foot square (up to 10 feet deep), casting takes 10 minutes. The maximum area, 750 feet by 750 feet, takes 4 hours and 10 minutes to move.</p>\n      <p>This spell does not violently break the surface of the ground. Instead, it creates wavelike crests and troughs, with the earth reacting with glacierlike fluidity until the desired result is achieved. Trees, structures, rock formations, and such are mostly unaffected except for changes in elevation and relative topography.</p>\n      <p>The spell cannot be used for tunneling and is generally too slow to trap or bury creatures. Its primary use is for digging or filling moats or for adjusting terrain contours before a battle.</p>\n      <p>This spell has no effect on earth creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Move Earth\" level=\"5\"><p><h5>Move Earth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Dirt in an area up to 750 ft. square and up to 10 ft. deep (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>Move earth</i> moves dirt (clay, loam, sand), possibly collapsing embankments, moving hillocks, shifting dunes, and so forth.</p><p>However, in no event can rock formations be collapsed or moved. The area to be affected determines the casting time. For every 150-foot square (up to 10 feet deep), casting takes 10 minutes. The maximum area, 750 feet by 750 feet, takes 4 hours and 10 minutes to move.</p><p>This spell does not violently break the surface of the ground. Instead, it creates wavelike crests and troughs, with the earth reacting with glacierlike fluidity until the desired result is achieved. Trees, structures, rock formations, and such are mostly unaffected except for changes in elevation and relative topography.</p><p>The spell cannot be used for tunneling and is generally too slow to trap or bury creatures. Its primary use is for digging or filling moats or for adjusting terrain contours before a battle.</p><p>This spell has no effect on earth creatures.</p><p><i>Material Component:</i> A mixture of soils (clay, loam, and sand) in a small bag, and an iron blade.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (451,'Neutralize Poison','neutralize poison','Conjuration','Healing',NULL,NULL,'Bard 4, Cleric 4, Druid 3, Paladin 4, Ranger 3','V, S, M/DF','1 standard action','Touch','Creature or object of up to 1 cu. ft./level touched',NULL,NULL,'10 min./level','Will negates (harmless, object)','Yes (harmless, object)','Immunizes subject against poison, detoxifies venom in or on subject.',NULL,NULL,'A bit of charcoal.',NULL,'\n      <p>You detoxify any sort of venom in the creature or object touched. A poisoned creature suffers no additional effects from the poison, and any temporary effects are ended, but the spell does not reverse instantaneous effects, such as hit point damage, temporary ability damage, or effects that don\'t go away on their own.</p>\n      <p>The creature is immune to any poison it is exposed to during the duration of the spell. Unlike with <i>delay poison</i>, such effects aren\'t postponed until after the duration -the creature need not make any saves against poison effects applied to it during the length of the spell.</p>\n      <p>This spell can instead neutralize the poison in a poisonous creature or object for the duration of the spell, at the caster\'s option.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Neutralize Poison\" level=\"5\"><p><h5>Neutralize Poison</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Cleric 4, Druid 3, Paladin 4, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature or object of up to 1 cu. ft./level touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p>You detoxify any sort of venom in the creature or object touched. A poisoned creature suffers no additional effects from the poison, and any temporary effects are ended, but the spell does not reverse instantaneous effects, such as hit point damage, temporary ability damage, or effects that don\'t go away on their own.</p><p>The creature is immune to any poison it is exposed to during the duration of the spell. Unlike with <i>delay poison</i>, such effects aren\'t postponed until after the duration -the creature need not make any saves against poison effects applied to it during the length of the spell.</p><p>This spell can instead neutralize the poison in a poisonous creature or object for the duration of the spell, at the caster\'s option.</p><p><i>Arcane Material Component:</i> A bit of charcoal.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (452,'Nightmare','nightmare','Illusion','Phantasm','Mind-Affecting, Evil',NULL,'Bard 5, Sorcerer/Wizard 5','V, S','10 minutes','Unlimited','One living creature',NULL,NULL,'Instantaneous','Will negates; see text','Yes','Sends vision dealing 1d10 damage, fatigue.',NULL,NULL,NULL,NULL,'\n      <p>You send a hideous and unsettling phantasmal vision to a specific creature that you name or otherwise specifically designate.</p>\n      <p>The <i>nightmare</i> prevents restful sleep and causes 1d10 points of damage. The <i>nightmare</i> leaves the subject fatigued and unable to regain arcane spells for the next 24 hours.</p>\n      <p>The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None<sup><b>1</b></sup><br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n</table>\n      <p/>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n</table>\n      <p><i>Dispel evil</i> cast on the subject while you are casting the spell dispels the <i>nightmare</i> and causes you to be stunned for 10 minutes per caster level of the <i>dispel evil</i>.</p>\n      <p>If the recipient is awake when the spell begins, you can choose to cease casting (ending the spell) or to enter a trance until the recipient goes to sleep, whereupon you become alert again and complete the casting. If you are disturbed during the trance, you must succeed on a Concentration check as if you were in the midst of casting a spell or the spell ends.</p>\n      <p>If you choose to enter a trance, you are not aware of your surroundings or the activities around you while in the trance.</p>\n      <p>You are defenseless, both physically and mentally, while in the trance. (You always fail any saving throw, for example.)</p>\n      <p>Creatures who don\'t sleep (such as elves, but not half-elves) or dream are immune to this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Nightmare\" level=\"5\"><p><h5>Nightmare</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Phantasm) [Mind-Affecting, Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Unlimited<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You send a hideous and unsettling phantasmal vision to a specific creature that you name or otherwise specifically designate.</p><p>The <i>nightmare</i> prevents restful sleep and causes 1d10 points of damage. The <i>nightmare</i> leaves the subject fatigued and unable to regain arcane spells for the next 24 hours.</p><p>The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None<sup><b>1</b></sup><br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n</table><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n</table><p><i>Dispel evil</i> cast on the subject while you are casting the spell dispels the <i>nightmare</i> and causes you to be stunned for 10 minutes per caster level of the <i>dispel evil</i>.</p><p>If the recipient is awake when the spell begins, you can choose to cease casting (ending the spell) or to enter a trance until the recipient goes to sleep, whereupon you become alert again and complete the casting. If you are disturbed during the trance, you must succeed on a Concentration check as if you were in the midst of casting a spell or the spell ends.</p><p>If you choose to enter a trance, you are not aware of your surroundings or the activities around you while in the trance.</p><p>You are defenseless, both physically and mentally, while in the trance. (You always fail any saving throw, for example.)</p><p>Creatures who don\'t sleep (such as elves, but not half-elves) or dream are immune to this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (453,'Nondetection','nondetection','Abjuration',NULL,NULL,NULL,'Ranger 4, Sorcerer/Wizard 3, Trickery 3','V, S, M','1 standard action','Touch','Creature or object touched',NULL,NULL,'1 hour/level','Will negates (harmless, object)','Yes (harmless, object)','Hides subject from divination, scrying.',NULL,'A pinch of diamond dust worth 50 gp.',NULL,NULL,'\n      <p>The warded creature or object becomes difficult to detect by divination spells such as <i>clairaudience/clairvoyance</i>,  <i>locate object</i>,  and <i>detect</i> spells. <i>Nondetection</i> also prevents location by such magic items as <i>crystal balls</i>. If a divination is attempted against the warded creature or item, the caster of the divination must succeed on a caster level check (1d20 + caster level) against a DC of 11 + the caster level of the spellcaster who cast <i>nondetection</i>. If you cast <i>Nondetection</i> on yourself or on an item currently in your possession, the DC is 15 + your caster level.</p>\n      <p>If cast on a creature, <i>Nondetection</i> wards the creature\'s gear as well as the creature itself.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Nondetection\" level=\"5\"><p><h5>Nondetection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Ranger 4, Sorcerer/Wizard 3, Trickery 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature or object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p>The warded creature or object becomes difficult to detect by divination spells such as <i>clairaudience/clairvoyance</i>,  <i>locate object</i>,  and <i>detect</i> spells. <i>Nondetection</i> also prevents location by such magic items as <i>crystal balls</i>. If a divination is attempted against the warded creature or item, the caster of the divination must succeed on a caster level check (1d20 + caster level) against a DC of 11 + the caster level of the spellcaster who cast <i>nondetection</i>. If you cast <i>Nondetection</i> on yourself or on an item currently in your possession, the DC is 15 + your caster level.</p><p>If cast on a creature, <i>Nondetection</i> wards the creature\'s gear as well as the creature itself.</p><p><i>Material Component:</i> A pinch of diamond dust worth 50 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (454,'Obscure Object','obscure object','Abjuration',NULL,NULL,NULL,'Bard 1, Cleric 3, Sorcerer/Wizard 2','V, S, M/DF','1 standard action','Touch','One object touched of up to 100 lb./level',NULL,NULL,'8 hours (D)','Will negates (object)','Yes (object)','Masks object against scrying.',NULL,NULL,'A piece of chameleon skin.',NULL,'\n      <p>This spell hides an object from location by divination (scrying) effects, such as the <i>scrying</i> spell or a <i>crystal ball</i>. Such an attempt automatically fails (if the divination is targeted on the object) or fails to perceive the object (if the divination is targeted on a nearby location, object, or person).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Obscure Object\" level=\"5\"><p><h5>Obscure Object</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 3, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One object touched of up to 100 lb./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>8 hours (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This spell hides an object from location by divination (scrying) effects, such as the <i>scrying</i> spell or a <i>crystal ball</i>. Such an attempt automatically fails (if the divination is targeted on the object) or fails to perceive the object (if the divination is targeted on a nearby location, object, or person).</p><p><i>Arcane Material Component:</i> A piece of chameleon skin.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (455,'Obscuring Mist','obscuring mist','Conjuration','Creation',NULL,NULL,'Air 1, Cleric 1, Druid 1, Sorcerer/Wizard 1, Water 1','V, S','1 standard action','20 ft.',NULL,NULL,'Cloud spreads in 20-ft. radius from you, 20 ft. high','1 min./level','None','No','Fog surrounds you.',NULL,NULL,NULL,NULL,'\n      <p>A misty vapor arises around you. It is stationary once created. The vapor obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target).</p>\n      <p>A moderate wind (11+ mph), such as from a <i>gust of wind</i> spell, disperses the fog in 4 rounds. A strong wind (21+ mph) disperses the fog in 1 round. A <i>fireball</i>,  <i>flame strike</i>, or similar spell burns away the fog in the explosive or fiery spell\'s area. A <i>wall of fire</i> burns away the fog in the area into which it deals damage.</p>\n      <p>This spell does not function underwater.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Obscuring Mist\" level=\"5\"><p><h5>Obscuring Mist</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 1, Cleric 1, Druid 1, Sorcerer/Wizard 1, Water 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Cloud spreads in 20-ft. radius from you, 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A misty vapor arises around you. It is stationary once created. The vapor obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target).</p><p>A moderate wind (11+ mph), such as from a <i>gust of wind</i> spell, disperses the fog in 4 rounds. A strong wind (21+ mph) disperses the fog in 1 round. A <i>fireball</i>,  <i>flame strike</i>, or similar spell burns away the fog in the explosive or fiery spell\'s area. A <i>wall of fire</i> burns away the fog in the area into which it deals damage.</p><p>This spell does not function underwater.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (456,'Open/Close','open/close','Transmutation',NULL,NULL,NULL,'Bard 0, Sorcerer/Wizard 0','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','Object weighing up to 30 lb. or portal that can be opened or closed',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','Opens or closes small or light things.',NULL,NULL,NULL,'A brass key.','\n      <p>You can open or close (your choice) a door, chest, box, window, bag, pouch, bottle, barrel, or other container. If anything resists this activity (such as a bar on a door or a lock on a chest), the spell fails. In addition, the spell can only open and close things weighing 30 pounds or less. Thus, doors, chests, and similar objects sized for enormous creatures may be beyond this spell\'s ability to affect.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Open/Close\" level=\"5\"><p><h5>Open/Close</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object weighing up to 30 lb. or portal that can be opened or closed<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You can open or close (your choice) a door, chest, box, window, bag, pouch, bottle, barrel, or other container. If anything resists this activity (such as a bar on a door or a lock on a chest), the spell fails. In addition, the spell can only open and close things weighing 30 pounds or less. Thus, doors, chests, and similar objects sized for enormous creatures may be beyond this spell\'s ability to affect.</p><p><i>Focus:</i> A brass key.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (457,'Order\'s Wrath','order\'s wrath','Evocation',NULL,'Lawful',NULL,'Law 4','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Nonlawful creatures within a burst that fills a 30-ft. cube',NULL,'Instantaneous (1 round); see text','Will partial; see text','Yes','Damages and dazes chaotic creatures.',NULL,NULL,NULL,NULL,'\n      <p>You channel lawful power to smite enemies. The power takes the form of a three-dimensional grid of energy. Only chaotic and neutral (not lawful) creatures are harmed by the spell.</p>\n      <p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to chaotic creatures (or 1d6 points of damage per caster level, maximum 10d6, to chaotic outsiders) and causes them to be dazed for 1 round. A successful Will save reduces the damage to half and negates the daze effect.</p>\n      <p>The spell deals only half damage to creatures who are neither chaotic nor lawful, and they are not dazed. They can reduce the damage in half again (down to one-quarter of the roll) with a successful Will save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Order\'s Wrath\" level=\"5\"><p><h5>Order\'s Wrath</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Lawful]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Law 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Nonlawful creatures within a burst that fills a 30-ft. cube<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous (1 round); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You channel lawful power to smite enemies. The power takes the form of a three-dimensional grid of energy. Only chaotic and neutral (not lawful) creatures are harmed by the spell.</p><p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to chaotic creatures (or 1d6 points of damage per caster level, maximum 10d6, to chaotic outsiders) and causes them to be dazed for 1 round. A successful Will save reduces the damage to half and negates the daze effect.</p><p>The spell deals only half damage to creatures who are neither chaotic nor lawful, and they are not dazed. They can reduce the damage in half again (down to one-quarter of the roll) with a successful Will save.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (458,'Overland Flight','overland flight','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S','1 standard action','Personal','You',NULL,NULL,'1 hour/level','Will negates (harmless)','Yes (harmless)','You fly at a speed of 40 ft. and can hustle over long distances.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like a <i>fly</i> spell, except you can fly at a speed of 40 feet (30 feet if wearing medium or heavy armor, or if carrying a medium or heavy load) with average maneuverability. When using this spell for long-distance movement, you can hustle without taking nonlethal damage (a forced march still requires Constitution checks). This means you can cover 64 miles in an eight-hour period of flight (or 48 miles at a speed of 30 feet).</p>\n      <p/>\n    ',NULL,'A wing feather from any bird.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Overland Flight\" level=\"5\"><p><h5>Overland Flight</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr></table><p>This spell functions like a <i>fly</i> spell, except you can fly at a speed of 40 feet (30 feet if wearing medium or heavy armor, or if carrying a medium or heavy load) with average maneuverability. When using this spell for long-distance movement, you can hustle without taking nonlethal damage (a forced march still requires Constitution checks). This means you can cover 64 miles in an eight-hour period of flight (or 48 miles at a speed of 30 feet).</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (459,'Owl\'s Wisdom','owl\'s wisdom','Transmutation',NULL,NULL,NULL,'Cleric 2, Druid 2, Paladin 2, Ranger 2, Sorcerer/Wizard 2','V, S, M/DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','Subject gains +4 to Wis for 1 min./level.',NULL,NULL,'A few feathers, or a pinch of droppings, from an owl.',NULL,'\n      <p>The transmuted creature becomes wiser. The spell grants a +4 enhancement bonus to Wisdom, adding the usual benefit to Wisdom-related skills. Clerics, druids, paladins, and rangers (and other Wisdom-based spellcasters) who receive <i>owl\'s wisdom</i> do not gain any additional bonus spells for the increased Wisdom, but the save DCs for their spells increase.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Owl\'s Wisdom\" level=\"5\"><p><h5>Owl\'s Wisdom</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Druid 2, Paladin 2, Ranger 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>The transmuted creature becomes wiser. The spell grants a +4 enhancement bonus to Wisdom, adding the usual benefit to Wisdom-related skills. Clerics, druids, paladins, and rangers (and other Wisdom-based spellcasters) who receive <i>owl\'s wisdom</i> do not gain any additional bonus spells for the increased Wisdom, but the save DCs for their spells increase.</p><p><i>Arcane Material Component:</i> A few feathers, or a pinch of droppings, from an owl.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (460,'Owl\'s Wisdom, Mass','mass owl\'s wisdom','Transmutation',NULL,NULL,NULL,'Cleric 6, Druid 6, Sorcerer/Wizard 6','V, S, M/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','As owl\'s wisdom, affects one subject/level.',NULL,NULL,'A few feathers, or a pinch of droppings, from an owl.',NULL,'\n      <p>This spell functions like <i>owl\'s wisdom</i>, except that it affects multiple creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Owl\'s Wisdom, Mass\" level=\"5\"><p><h5>Owl\'s Wisdom, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Druid 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>owl\'s wisdom</i>, except that it affects multiple creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsM-O');
INSERT INTO spell VALUES (461,'Passwall','passwall','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S, M','1 standard action','Touch',NULL,NULL,'5 ft. by 8 ft. opening, 10 ft. deep plus 5 ft. deep per three additional levels','1 hour/level (D)','None','No','Creates passage through wood or stone wall.',NULL,'A pinch of sesame seeds.',NULL,NULL,'\n      <p>You create a passage through wooden, plaster, or stone walls, but not through metal or other harder materials. The passage is 10 feet deep plus an additional 5 feet deep per three caster levels above 9th (15 feet at 12th, 20 feet at 15th, and a maximum of 25 feet deep at 18th level). If the wall\'s thickness is more than the depth of the passage created, then a single <i>passwall</i> simply makes a niche or short tunnel. Several <i>passwall</i> spells can then form a continuing passage to breach very thick walls. When <i>passwall</i> ends, creatures within the passage are ejected out the nearest exit. If someone dispels the <i>passwall</i> or you dismiss it, creatures in the passage are ejected out the far exit, if there is one, or out the sole exit if there is only one.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Passwall\" level=\"5\"><p><h5>Passwall</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>5 ft. by 8 ft. opening, 10 ft. deep plus 5 ft. deep per three additional levels<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You create a passage through wooden, plaster, or stone walls, but not through metal or other harder materials. The passage is 10 feet deep plus an additional 5 feet deep per three caster levels above 9th (15 feet at 12th, 20 feet at 15th, and a maximum of 25 feet deep at 18th level). If the wall\'s thickness is more than the depth of the passage created, then a single <i>passwall</i> simply makes a niche or short tunnel. Several <i>passwall</i> spells can then form a continuing passage to breach very thick walls. When <i>passwall</i> ends, creatures within the passage are ejected out the nearest exit. If someone dispels the <i>passwall</i> or you dismiss it, creatures in the passage are ejected out the far exit, if there is one, or out the sole exit if there is only one.</p><p><i>Material Component:</i> A pinch of sesame seeds.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (462,'Pass without Trace','pass without trace','Transmutation',NULL,NULL,NULL,'Druid 1, Ranger 1','V, S, DF','1 standard action','Touch','One creature/level touched',NULL,NULL,'1 hour/level (D)','Will negates (harmless)','Yes (harmless)','One subject/level leaves no tracks.',NULL,NULL,NULL,NULL,'\n      <p>The subject or subjects can move through any type of terrain and leave neither footprints nor scent. Tracking the subjects is impossible by nonmagical means.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Pass without Trace\" level=\"5\"><p><h5>Pass without Trace</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject or subjects can move through any type of terrain and leave neither footprints nor scent. Tracking the subjects is impossible by nonmagical means.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (463,'Permanency','permanency','Universal',NULL,NULL,NULL,'Sorcerer/Wizard 5','V, S, XP','2 rounds','See text','See text','See text','See text','Permanent; see text','None','No','Makes certain spells permanent.',NULL,NULL,NULL,NULL,'\n      <p>This spell makes certain other spells permanent.</p>\n      <p>Depending on the spell, you must be of a minimum caster level and must expend a number of XP.</p>\n      <p>You can make the following spells permanent in regard to yourself.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Spell</b><br/></td> <td><b>Minimum Caster Level</b><br/></td>\n<td><b>XP Cost</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Arcane sight</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Comprehend languages</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Darkvision</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Detect magic</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Read magic</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>See invisibility</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Tongues</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n</table>\n      <p>You cast the desired spell and then follow it with the <i>permanency</i> spell. You cannot cast these spells on other creatures. This application of <i>permanency</i> can be dispelled only by a caster of higher level than you were when you cast the spell.</p>\n      <p>In addition to personal use, <i>permanency</i> can be used to make the following spells permanent on yourself, another creature, or an object (as appropriate).</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Spell</b><br/></td>\n<td><b>Minimum Caster Level</b><br/></td>\n<td><b>XP Cost</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Enlarge person</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Magic fang</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Magic fang</i>,  <i>greater</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>reduce person</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Resistance</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Telepathic bond</i>\n<sup><b>1</b></sup><br/></td>\n<td>13th<br/></td>\n<td>2,500 XP<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"2\">\n<td colspan=\"3\">1 Only bonds two creatures per casting of <i>permanency</i>.<br/></td>\n\n</tr>\n</table>\n      <p>Additionally, the following spells can be cast upon objects or areas only and rendered permanent.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Spell</b><br/></td> <td><b>Minimum Caster Level</b><br/></td>\n<td><b>XP Cost</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Alarm</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Animate objects</i><br/></td>\n<td>14th<br/></td>\n<td>3,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Dancing lights</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Ghost sound</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Gust of wind</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Invisibility</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Mage\'s private sanctum</i><br/></td>\n<td>13th<br/></td>\n<td>2,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Magic mouth</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Phase door</i><br/></td>\n<td>15th<br/></td>\n<td>3,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Prismatic sphere</i><br/></td>\n<td>17th<br/></td>\n<td>4,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>prismatic wall</i><br/></td>\n<td>16th<br/></td>\n<td>4,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Shrink item</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Solid fog</i><br/></td>\n<td>12th<br/></td>\n<td>2,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Stinking cloud</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of death</i><br/></td>\n<td>16th<br/></td>\n<td>4,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of fear</i><br/></td>\n<td>14th<br/></td>\n<td>3,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of insanity</i><br/></td>\n<td>16th<br/></td>\n<td>4,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of pain</i><br/></td>\n<td>13th<br/></td>\n<td>2,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of persuasion</i><br/></td>\n<td>14th<br/></td>\n<td>3,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of sleep</i><br/></td>\n<td>16th<br/></td>\n<td>4,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of stunning</i><br/></td>\n<td>15th<br/></td>\n<td>3,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Symbol of weakness</i><br/></td>\n<td>15th<br/></td>\n<td>3,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Teleportation circle</i><br/></td>\n<td>17th<br/></td>\n<td>4,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Wall of fire</i><br/></td>\n<td>12th<br/></td>\n<td>2,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Wall of force</i><br/></td>\n<td>13th<br/></td>\n<td>2,500 XP<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Web</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n</table>\n      <p>Spells cast on other creatures, objects, or locations (not on you) are vulnerable to <i>dispel magic</i> as normal.</p>\n      <p/>\n    ','See tables above.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Permanency\" level=\"5\"><p><h5>Permanency</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Universal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>2 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target, Effect, or Area:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell makes certain other spells permanent.</p><p>Depending on the spell, you must be of a minimum caster level and must expend a number of XP.</p><p>You can make the following spells permanent in regard to yourself.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Spell</b><br/></td> <td><b>Minimum Caster Level</b><br/></td>\n<td><b>XP Cost</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Arcane sight</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Comprehend languages</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Darkvision</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Detect magic</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Read magic</i><br/></td>\n<td>9th<br/></td>\n<td>500 XP<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>See invisibility</i><br/></td>\n<td>10th<br/></td>\n<td>1,000 XP<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><i>Tongues</i><br/></td>\n<td>11th<br/></td>\n<td>1,500 XP<br/></td>\n\n</tr>\n</table><p>You cast the desired spell and then follow it with the <i>permanency</i> spell. You cannot cast these spells on other creatures. This application of <i>permanency</i> can be dispelled only by a caster of higher level than you were when you cast the spell.</p><p>In addition to personal use, <i>permanency</i> can be used to make the following spells permanent on yourself, another creature, or an object (as appropriate).</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Spell</b><br/></td>\n<td><b>Minimum Caster Level</b><br/></td>\n<td